import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
})
export class HomeComponent {
}
<div class="hero-section">
  <h1>Welcome to PriceFlow</h1>
  <p>Analyze the latest trends and make informed decisions</p>
  <button class="get-started-btn">Get Started</button>
</div>

<style>
  .hero-section {
    height: 100vh;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    text-align: center;
    background-image: url('../../assets/smbackground.jpg');
    background-size: contain;
    background-position: center;
    color: white;
    text-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
  }

  h1 {
    font-size: 3.5rem;
    margin-bottom: 1rem;
  }

  p {
    font-size: 1.5rem;
    margin-bottom: 2rem;
  }

  .get-started-btn {
    padding: 1rem 2rem;
    font-size: 1.2rem;
    background-color: #007bff;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;
    transition: background-color 0.3s;
  }

    .get-started-btn:hover {
      background-color: #0056b3;
    }
</style>
